'use client';

import { useState, useEffect } from 'react';
import { 
  Search, 
  MapPin, 
  Clock, 
  DollarSign, 
  ChevronDown, 
  Briefcase,
  AlertTriangle,
  Database
} from 'lucide-react';
import { useAutomation } from '@/hooks/useLuminal';
import { seedDemoData } from '@/app/actions/seed';
import { useRouter } from 'next/navigation';

export function JobsClient({ initialJobs }: { initialJobs: any[] }) {
  const [search, setSearch] = useState('');
  const [jobs, setJobs] = useState(initialJobs);
  const [applyingId, setApplyingId] = useState<string | null>(null);
  const [isSeeding, setIsSeeding] = useState(false);
  const [platformFilter, setPlatformFilter] = useState('All Platforms');
  const [jobTypeFilter, setJobTypeFilter] = useState('Job Type');
  const [scoreFilter, setScoreFilter] = useState('Score 80%+');
  const [salaryFilter, setSalaryFilter] = useState('Salary');
  const router = useRouter();

  // Sync state when props change (after router.refresh)
  useEffect(() => {
    setJobs(initialJobs);
  }, [initialJobs]);
  
  const { apply } = useAutomation();

  const handleApply = async (job: any) => {
    setApplyingId(job.id);
    const success = await apply(job.id, job.title, job.company);
    
    if (success) {
      setJobs(prev => prev.map(j => j.id === job.id ? { ...j, status: 'APPLIED' } : j));
    } else {
      alert("Failed to auto-apply via API");
    }
    setApplyingId(null);
  };

  const handleSeed = async () => {
    setIsSeeding(true);
    try {
      await seedDemoData();
      router.refresh();
    } catch (e) {
      alert("Seeding failed");
    } finally {
      setIsSeeding(false);
    }
  };

  const getPlatformClass = (platform: string) => {
    switch (platform?.toUpperCase()) {
      case 'LINKEDIN': return 'bg-blue-900/40 text-blue-400 border-blue-400/20';
      case 'INDEED': return 'bg-orange-900/40 text-orange-400 border-orange-400/20';
      case 'NAUKRI': return 'bg-green-900/40 text-green-400 border-green-400/20';
      case 'GLASSDOOR': return 'bg-purple-900/40 text-purple-400 border-purple-400/20';
      default: return 'bg-gray-800 text-gray-400 border-gray-400/20';
    }
  };

  const filteredJobs = jobs.filter(j => {
    const matchesSearch = j.title.toLowerCase().includes(search.toLowerCase()) || 
                          j.company.toLowerCase().includes(search.toLowerCase());
    
    // Extract base platform name (e.g. Naukri.com -> naukri)
    const normalizedFilter = platformFilter.replace('.com', '').toLowerCase();
    const matchesPlatform = platformFilter === 'All Platforms' || 
                            j.source?.toLowerCase().includes(normalizedFilter);
                            
    const matchesJobType = jobTypeFilter === 'Job Type' || jobTypeFilter === 'All Types' ||
                           j.title.toLowerCase().includes(jobTypeFilter.toLowerCase()) ||
                           (jobTypeFilter === 'Remote' && j.location?.toLowerCase().includes('remote'));

    let matchesScore = true;
    if (scoreFilter !== 'All Scores' && scoreFilter !== 'Score 80%+ (Default)') {
      // Default score 'Score 80%+' might be standard, we can parse it
      const matchRequirement = parseInt(scoreFilter.replace(/[^0-9]/g, ''));
      if (!isNaN(matchRequirement)) {
        matchesScore = (j.matchScore || 0) >= matchRequirement;
      }
    }

    const matchesSalary = true; // Salary formatting depends on detailed demo data
                            
    return matchesSearch && matchesPlatform && matchesJobType && matchesScore && matchesSalary;
  });

  return (
    <main className="pl-[220px] pt-[52px] pb-24 min-h-screen">
      <div className="max-w-[1240px] mx-auto p-8">
        
        {/* Header Row */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-[28px] font-bold text-text-primary">Job Matches</h1>
            <p className="text-text-muted mt-1">Discover your high-affinity roles curated by Luminal AI.</p>
          </div>
          
          <button 
            onClick={handleSeed}
            disabled={isSeeding}
            className="flex items-center gap-2 px-4 py-2 bg-accent-primary/10 border border-accent-primary/20 text-accent-primary rounded-lg text-sm font-bold hover:bg-accent-primary/20 transition-all disabled:opacity-50"
          >
            <Database size={16} />
            {isSeeding ? 'Seeding...' : 'Seed Demo Data'}
          </button>
        </div>

        {/* Search + Filter Bar */}
        <div className="bg-card-surface border border-border-color p-3.5 rounded-xl mb-8 flex items-center justify-between gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-text-hint" size={18} />
            <input 
              type="text" 
              placeholder="Search roles, skills, or companies..."
              className="w-full pl-11 pr-4 py-2.5 bg-[#1a1a28] border border-[#2a2a40] text-text-primary rounded-lg outline-none focus:border-accent-primary transition-colors text-sm"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 relative z-20">
            {[
              { id: 'platform', val: platformFilter, set: setPlatformFilter, opts: ['All Platforms', 'Naukri.com', 'LinkedIn', 'Indeed', 'Glassdoor'] },
              { id: 'jobType', val: jobTypeFilter, set: setJobTypeFilter, opts: ['Job Type', 'Full-time', 'Part-time', 'Contract', 'Internship', 'Remote'] },
              { id: 'score', val: scoreFilter, set: setScoreFilter, opts: ['All Scores', 'Score 90%+', 'Score 80%+', 'Score 70%+', 'Score 60%+'] },
              { id: 'salary', val: salaryFilter, set: setSalaryFilter, opts: ['Salary', '$50k+', '$100k+', '$150k+', '$200k+'] }
            ].map((filterDef) => (
              <div key={filterDef.id} className="relative group">
                <button 
                  className="px-4 py-2.5 bg-[#1a1a28] border border-[#2a2a40] text-text-primary text-xs font-medium rounded-lg flex items-center gap-2 hover:border-accent-primary transition-colors whitespace-nowrap min-w-[110px] justify-between"
                >
                  {filterDef.val}
                  <ChevronDown size={14} className="text-text-hint shrink-0" />
                </button>
                <div className="absolute top-full mt-2 left-0 min-w-[140px] bg-[#1a1a28] border border-[#2a2a40] rounded-lg shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all py-1 z-30">
                  {filterDef.opts.map(opt => (
                    <button 
                      key={opt} 
                      onClick={() => filterDef.set(opt)}
                      className="w-full text-left px-4 py-2 text-xs text-text-muted hover:text-text-primary hover:bg-[#2a2a40] transition-colors"
                    >
                      {opt}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Jobs Grid */}
        {filteredJobs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 bg-card-surface border border-dashed border-border-color rounded-xl">
             <Briefcase size={48} className="text-text-hint mb-4" />
             <h3 className="text-lg font-bold text-text-primary">No Jobs Found</h3>
             <p className="text-text-muted text-sm">Use the 'Seed Demo Data' button to populate your workspace.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            {filteredJobs.map((job) => (
              <div key={job.id} className="bg-card-surface border border-border-color rounded-xl p-5 relative group hover:border-[#3a2e80] transition-colors">
                
                {job.status === 'APPLIED' && (
                  <div className="absolute top-0 right-0 px-3 py-1 bg-teal-500 text-white text-[10px] font-bold rounded-tr-xl rounded-bl-xl uppercase tracking-wider">
                    Applied
                  </div>
                )}

                {/* Top Row */}
                <div className="flex items-start justify-between mb-4">
                  <div className="flex gap-4">
                    <div className="w-10 h-10 rounded-lg bg-[#1a1a28] border border-border-color flex items-center justify-center shrink-0">
                      <Briefcase size={20} className="text-text-muted" />
                    </div>
                    <div>
                      <h3 className="text-[17px] font-bold text-text-primary leading-tight">{job.title}</h3>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-sm text-text-muted">{job.company}</span>
                        <span className={`px-2 py-0.5 border rounded text-[9px] font-bold tracking-wider ${getPlatformClass(job.source)}`}>
                          {job.source || 'WEB'}
                        </span>
                        <span className="text-text-hint">·</span>
                        <span className="text-xs text-text-muted">NEW</span>
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-bold text-teal-500">{job.matchScore || 0}% MATCH SCORE</div>
                    <div className="w-full h-1 bg-border-color rounded-full mt-1.5 overflow-hidden">
                      <div 
                        className="h-full bg-teal-500 rounded-full" 
                        style={{ width: `${job.matchScore || 0}%` }}
                      />
                    </div>
                  </div>
                </div>

                {/* Info Row */}
                <div className="grid grid-cols-3 gap-2 mb-4">
                  <div className="flex items-center gap-1.5 text-[12px] text-text-muted">
                    <MapPin size={14} className="text-text-hint" />
                    <span className="truncate">{job.location}</span>
                  </div>
                  <div className="flex items-center gap-1.5 text-[12px] text-text-muted">
                    <Clock size={14} className="text-text-hint" />
                    <span>RECENT</span>
                  </div>
                  <div className="flex items-center gap-1.5 text-[12px] text-text-muted">
                    <DollarSign size={14} className="text-text-hint" />
                    <span className="truncate">N/A</span>
                  </div>
                </div>

                {/* Action Row */}
                <div className="flex items-center justify-between pt-4 border-t border-border-color">
                  {job.status === 'APPLIED' ? (
                    <div className="flex items-center gap-4">
                      <span className="text-xs font-semibold text-text-muted uppercase tracking-wider">Application Sent</span>
                      <button className="text-xs font-bold text-accent-primary hover:underline">Follow Up</button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => handleApply(job)}
                      disabled={applyingId === job.id}
                      className="flex-1 bg-accent-primary hover:bg-opacity-90 text-white text-xs font-bold py-2.5 rounded-lg transition-all mr-6 disabled:opacity-50"
                    >
                      {applyingId === job.id ? 'Starting Application...' : 'Auto Apply'}
                    </button>
                  )}
                  <button className="text-xs font-bold text-text-primary hover:text-accent-primary transition-colors whitespace-nowrap">
                    View Details
                  </button>
                </div>

              </div>
            ))}
          </div>
        )}
      </div>
    </main>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Bell, Zap, CheckCircle, AlertCircle, Info, X, Filter, Check } from 'lucide-react';

export function NotificationCenter({ userId }: { userId?: string }) {
  const [isOpen, setIsOpen] = useState(false);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [filterType, setFilterType] = useState<string | null>(null);
  const router = useRouter();

  // Simulation: In a real app, this would be a polling or websocket connection
  useEffect(() => {
    // Initial fetch from DB would happen here
    setNotifications([
      { id: '1', title: 'Application Submitted', message: 'Applied to Senior Frontend Engineer at TechPulse', type: 'SUCCESS', isRead: false, createdAt: new Date() },
      { id: '2', title: 'Agent Feedback', message: 'Your resume has been optimized for the Fintech Role.', type: 'AGENT', isRead: false, createdAt: new Date(Date.now() - 3600000) },
      { id: '3', title: 'New Job Match', message: 'A 92% match was found on LinkedIn: Staff Engineer.', type: 'INFO', isRead: false, createdAt: new Date(Date.now() - 7200000) },
    ]);
  }, []);

  const markAllRead = () => {
    setNotifications(prev => prev.map(n => ({...n, isRead: true})));
  };

  const handleNotificationClick = (n: any) => {
    setNotifications(prev => prev.map(prevN => prevN.id === n.id ? { ...prevN, isRead: true } : prevN));
    setIsOpen(false);
    
    if (n.type === 'SUCCESS' || n.type === 'INFO') {
      router.push('/jobs');
    } else if (n.type === 'AGENT') {
      router.push('/resume');
    }
  };

  const unreadCount = notifications.filter(n => !n.isRead).length;
  const displayedNotifications = filterType ? notifications.filter(n => n.type === filterType) : notifications;

  const getIcon = (type: string) => {
    switch (type) {
      case 'SUCCESS': return <CheckCircle size={16} className="text-green-400" />;
      case 'AGENT': return <Zap size={16} className="text-accent-primary" />;
      case 'WARNING': return <AlertCircle size={16} className="text-amber-500" />;
      default: return <Info size={16} className="text-blue-400" />;
    }
  };

  return (
    <div className="relative">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`relative p-2 rounded-lg transition-colors ${isOpen ? 'bg-accent-primary/20 text-accent-primary' : 'text-text-muted hover:text-text-primary'}`}
      >
        <Bell size={20} fill={isOpen ? "currentColor" : "none"} />
        {unreadCount > 0 && (
          <span className="absolute top-1 right-1 w-2 h-2 bg-[#ef4444] rounded-full border-2 border-sidebar-bg" />
        )}
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
          <div className="absolute right-0 mt-2 w-80 bg-sidebar-bg border border-border-color rounded-xl shadow-2xl z-50 overflow-hidden">
            <div className="p-4 border-b border-border-color flex flex-col gap-4 bg-card-surface">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-bold text-text-muted uppercase tracking-widest">Notification Agent</span>
                <button 
                  onClick={() => setNotifications([])}
                  className="text-[9px] font-bold text-text-hint hover:text-text-primary uppercase tracking-tighter"
                >
                  Clear All
                </button>
              </div>
              <div className="flex items-center justify-between mt-1 pt-1">
                <div className="relative group">
                  <button className="flex items-center gap-2 px-3 py-1.5 border border-border-color rounded-lg text-xs font-bold text-text-primary hover:bg-[#1a1a28] transition-colors">
                    <Filter size={14} />
                    Filters
                  </button>
                  <div className="absolute top-full mt-1 left-0 w-32 bg-[#1a1a28] border border-border-color rounded-lg shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-20">
                    {['ALL', 'SUCCESS', 'AGENT', 'INFO'].map(type => (
                      <button 
                        key={type}
                        onClick={() => setFilterType(type === 'ALL' ? null : type)}
                        className={`w-full text-left px-3 py-2 text-[11px] font-bold transition-colors ${filterType === type || (type === 'ALL' && !filterType) ? 'text-accent-primary bg-[#2a2a40]' : 'text-text-muted hover:text-text-primary hover:bg-[#2a2a40]'}`}
                      >
                        {type === 'ALL' ? 'All Types' : type}
                      </button>
                    ))}
                  </div>
                </div>
                <button 
                  onClick={markAllRead}
                  className="flex items-center gap-1.5 text-[13px] font-bold text-[#6366f1] hover:text-accent-primary transition-colors pr-1"
                >
                  <Check size={16} />
                  Mark all read
                </button>
              </div>
            </div>
            
            <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
              {displayedNotifications.length > 0 ? (
                displayedNotifications.map((n) => (
                  <button 
                    key={n.id} 
                    onClick={() => handleNotificationClick(n)}
                    className={`w-full text-left p-4 border-b border-border-color/50 hover:bg-[#1a1a28] transition-colors group block ${!n.isRead ? 'bg-[#1a1a28]/40' : ''}`}
                  >
                    <div className="flex gap-3 relative">
                      {!n.isRead && (
                        <div className="absolute top-1.5 -left-1.5 w-1.5 h-1.5 bg-accent-primary rounded-full shadow-[0_0_8px_rgba(79,107,237,0.8)]" />
                      )}
                      <div className="mt-0.5">{getIcon(n.type)}</div>
                      <div className="flex-1">
                        <h4 className="text-sm font-bold text-text-primary mb-1">{n.title}</h4>
                        <p className="text-[12px] text-text-muted leading-snug">{n.message}</p>
                        <span className="text-[10px] text-text-hint mt-2 block italic">
                          {new Date(n.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      </div>
                    </div>
                  </button>
                ))
              ) : (
                <div className="p-8 text-center flex flex-col items-center gap-3">
                  <div className="w-12 h-12 rounded-full bg-input-bg flex items-center justify-center text-text-hint">
                    <Bell size={24} />
                  </div>
                  <p className="text-xs text-text-muted">No new activity found.</p>
                </div>
              )}
            </div>
            
            <div className="p-3 bg-card-surface border-t border-border-color">
              <button 
                onClick={() => {
                  setIsOpen(false);
                  alert('Full Activity Log interface is arriving in the next major build!');
                }}
                className="w-full py-1.5 text-[10px] font-bold text-text-muted hover:text-accent-primary uppercase tracking-widest transition-colors"
              >
                View Full Activity Log
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { User, Code2, Briefcase, Plus, X, Sparkles, MessageCircle } from 'lucide-react';
import { saveProfile } from '@/app/actions/profile';

export function ProfileForm({ initialProfile, userEmail }: { initialProfile: any, userEmail: string }) {
  const [isSaving, setIsSaving] = useState(false);
  const [successMsg, setSuccessMsg] = useState("");
  
  const [formData, setFormData] = useState({
    fullName: initialProfile?.fullName || initialProfile?.user?.name || '',
    email: initialProfile?.email || userEmail || '',
    headline: initialProfile?.headline || '',
    githubUrl: initialProfile?.githubUrl || '',
    portfolioUrl: initialProfile?.portfolioUrl || '',
    skills: initialProfile?.skills?.length ? initialProfile.skills.map((s: { name: string }) => s.name) : ['React', 'Node.js'],
    experience: initialProfile?.experience || [],
    education: initialProfile?.education || [],
    projects: initialProfile?.projects || [],
    certificates: initialProfile?.certificates || []
  });

  const [newSkill, setNewSkill] = useState("");

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await saveProfile(formData);
      setSuccessMsg("Profile saved successfully!");
      setTimeout(() => setSuccessMsg(""), 3000);
    } catch (e: unknown) {
      alert("Error saving: " + e.message);
    }
    setIsSaving(false);
  };

  const addSkill = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSkill.trim()) return;
    if (!formData.skills.includes(newSkill.trim())) {
      setFormData({ ...formData, skills: [...formData.skills, newSkill.trim()] });
    }
    setNewSkill("");
  };

  const removeSkill = (skillToRemove: string) => {
    setFormData({ ...formData, skills: formData.skills.filter(s => s !== skillToRemove) });
  };

  const addExperience = () => {
    setFormData({ ...formData, experience: [...formData.experience, { title: '', company: '', period: '', description: '' }] });
  };

  const updateExperience = (index: number, field: string, value: string) => {
    const nextExp = [...formData.experience];
    nextExp[index] = { ...nextExp[index], [field]: value };
    setFormData({ ...formData, experience: nextExp });
  };

  const removeExperience = (index: number) => {
    setFormData({ ...formData, experience: formData.experience.filter((_: any, i: number) => i !== index) });
  };

  const addProject = () => {
    setFormData({ ...formData, projects: [...formData.projects, { name: '', description: '', link: '' }] });
  };

  const updateProject = (index: number, field: string, value: string) => {
    const nextProj = [...formData.projects];
    nextProj[index] = { ...nextProj[index], [field]: value };
    setFormData({ ...formData, projects: nextProj });
  };

  const addEducation = () => {
    setFormData({ ...formData, education: [...formData.education, { school: '', degree: '', period: '' }] });
  };

  const updateEducation = (index: number, field: string, value: string) => {
    const nextEdu = [...formData.education];
    nextEdu[index] = { ...nextEdu[index], [field]: value };
    setFormData({ ...formData, education: nextEdu });
  };

  return (
    <>
      <div className="grid grid-cols-12 gap-6">
        {/* Personal Details */}
        <div className="col-span-7 glass-card p-6">
          <div className="flex items-center gap-2 mb-6">
            <User size={20} className="text-accent-primary" />
            <h2 className="text-lg font-semibold text-text-primary">Personal Details</h2>
          </div>

          <div className="grid grid-cols-2 gap-4 mb-4">
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-text-muted uppercase">Full Name</label>
              <input 
                type="text" 
                value={formData.fullName}
                onChange={e => setFormData({...formData, fullName: e.target.value})}
                className="input-field"
                placeholder="John Doe"
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-text-muted uppercase">Email</label>
              <input 
                type="email" 
                value={formData.email}
                onChange={e => setFormData({...formData, email: e.target.value})}
                className="input-field"
              />
            </div>
          </div>

          <div className="flex flex-col gap-2 mb-4">
            <label className="text-xs font-medium text-text-muted uppercase">Headline</label>
            <input 
              type="text" 
              value={formData.headline}
              onChange={e => setFormData({...formData, headline: e.target.value})}
              className="input-field"
              placeholder="e.g. Senior Software Engineer"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-text-muted uppercase">GitHub URL</label>
              <input 
                type="text" 
                value={formData.githubUrl}
                onChange={e => setFormData({...formData, githubUrl: e.target.value})}
                className="input-field"
                placeholder="https://github.com/..."
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-text-muted uppercase">Portfolio/Portfolio</label>
              <input 
                type="text" 
                value={formData.portfolioUrl}
                onChange={e => setFormData({...formData, portfolioUrl: e.target.value})}
                className="input-field"
                placeholder="https://yourwork.com"
              />
            </div>
          </div>
        </div>

        {/* ATS Readiness */}
        <div className="col-span-5 glass-card p-6 flex flex-col items-center justify-center text-center">
          <div className="relative w-[140px] h-[140px] mb-4">
            {/* SVG Donut Chart */}
            <svg className="w-full h-full transform -rotate-90">
              <circle
                cx="70"
                cy="70"
                r="60"
                stroke="currentColor"
                strokeWidth="8"
                fill="transparent"
                className="text-border-color"
              />
              <circle
                cx="70"
                cy="70"
                r="60"
                stroke="currentColor"
                strokeWidth="8"
                fill="transparent"
                strokeDasharray={2 * Math.PI * 60}
                strokeDashoffset={2 * Math.PI * 60 * (1 - ((initialProfile?.atsScore || 50) / 100))}
                strokeLinecap="round"
                className="text-accent-primary"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-28px font-bold text-text-primary leading-none">{initialProfile?.atsScore || 50}%</span>
            </div>
          </div>
          <span className="text-[11px] font-bold text-text-muted uppercase tracking-wider">ATS READINESS</span>
        </div>

        {/* Technical Skills */}
        <div className="col-span-12 glass-card p-6">
          <div className="flex items-center gap-2 mb-6">
            <Code2 size={20} className="text-accent-primary" />
            <h2 className="text-lg font-semibold text-text-primary">Technical Skills</h2>
          </div>

          <div className="flex flex-wrap gap-3 mb-4">
            {formData.skills.map((skill: string) => (
              <div key={skill} className="skill-pill group">
                {skill}
                <button 
                  onClick={() => removeSkill(skill)}
                  className="hover:text-white transition-colors"
                >
                  <X size={12} />
                </button>
              </div>
            ))}
          </div>
          
          <form onSubmit={addSkill} className="flex items-center gap-2 max-w-[300px]">
             <input 
               type="text" 
               value={newSkill}
               onChange={e => setNewSkill(e.target.value)}
               placeholder="React, AWS, etc..."
               className="input-field !h-8 text-sm"
             />
             <button type="submit" className="px-3 h-8 border border-dashed border-[#3a2a60] text-text-muted rounded-full text-xs hover:border-accent-primary hover:text-text-primary transition-colors flex items-center gap-1 shrink-0">
                <Plus size={12} />
                Add
             </button>
          </form>
        </div>

        {/* Experience Section */}
        <div className="col-span-12 glass-card p-6">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <Briefcase size={20} className="text-accent-primary" />
              <h2 className="text-lg font-semibold text-text-primary">Experience</h2>
            </div>
            <button onClick={addExperience} className="text-xs font-bold text-accent-primary hover:underline flex items-center gap-1">
              <Plus size={14} /> Add Role
            </button>
          </div>

          <div className="flex flex-col gap-6">
            {formData.experience.map((exp: any, i: number) => (
              <div key={i} className="bg-[#1a1a28]/40 border border-border-color p-4 rounded-xl relative">
                <button onClick={() => removeExperience(i)} className="absolute top-4 right-4 text-text-muted hover:text-red-500">
                  <X size={16} />
                </button>
                <div className="grid grid-cols-3 gap-4 mb-4">
                  <input placeholder="Job Title" value={exp.title} onChange={e => updateExperience(i, 'title', e.target.value)} className="input-field" />
                  <input placeholder="Company" value={exp.company} onChange={e => updateExperience(i, 'company', e.target.value)} className="input-field" />
                  <input placeholder="Period (e.g. 2021 - Present)" value={exp.period} onChange={e => updateExperience(i, 'period', e.target.value)} className="input-field" />
                </div>
                <textarea 
                  placeholder="Key Responsibilities & Achievements" 
                  value={exp.description} 
                  onChange={e => updateExperience(i, 'description', e.target.value)}
                  className="input-field w-full h-24 resize-none py-3"
                />
              </div>
            ))}
          </div>
        </div>

        {/* Projects & Education */}
        <div className="col-span-6 glass-card p-6">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <Code2 size={20} className="text-accent-primary" />
              <h2 className="text-lg font-semibold text-text-primary">Projects</h2>
            </div>
            <button onClick={addProject} className="text-xs font-bold text-accent-primary hover:underline flex items-center gap-1">
              <Plus size={14} /> Add
            </button>
          </div>
          <div className="flex flex-col gap-4">
            {formData.projects.map((p: any, i: number) => (
              <div key={i} className="flex flex-col gap-2 p-3 bg-sidebar-bg/50 border border-border-color rounded-lg">
                <input placeholder="Project Name" value={p.name} onChange={e => updateProject(i, 'name', e.target.value)} className="input-field !h-9 text-sm" />
                <input placeholder="Link" value={p.link} onChange={e => updateProject(i, 'link', e.target.value)} className="input-field !h-9 text-sm" />
                <textarea placeholder="Brief summary" value={p.description} onChange={e => updateProject(i, 'description', e.target.value)} className="input-field !h-16 text-[12px] py-2" />
              </div>
            ))}
          </div>
        </div>

        <div className="col-span-6 glass-card p-6">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <Sparkles size={20} className="text-accent-primary" />
              <h2 className="text-lg font-semibold text-text-primary">Education</h2>
            </div>
            <button onClick={addEducation} className="text-xs font-bold text-accent-primary hover:underline flex items-center gap-1">
              <Plus size={14} /> Add
            </button>
          </div>
          <div className="flex flex-col gap-4">
            {formData.education.map((e: any, i: number) => (
              <div key={i} className="flex flex-col gap-2 p-3 bg-sidebar-bg/50 border border-border-color rounded-lg">
                <input placeholder="School/University" value={e.school} onChange={e => updateEducation(i, 'school', e.target.value)} className="input-field !h-9 text-sm" />
                <input placeholder="Degree" value={e.degree} onChange={e => updateEducation(i, 'degree', e.target.value)} className="input-field !h-9 text-sm" />
                <input placeholder="Period" value={e.period} onChange={e => updateEducation(i, 'period', e.target.value)} className="input-field !h-9 text-sm" />
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* BOTTOM CTA */}
      <div className="fixed bottom-0 left-[220px] right-[320px] p-6 pointer-events-none z-40">
        <div className="max-w-[1000px] mx-auto pointer-events-auto flex flex-col items-center">
          {successMsg && (
            <div className="mb-4 px-4 py-2 rounded-full bg-green-500/20 text-green-400 font-bold text-sm border border-green-500/30">
              {successMsg}
            </div>
          )}
          <button 
            onClick={handleSave}
            disabled={isSaving}
            className="w-full h-14 rounded-xl bg-gradient-to-r from-[#5b4fd4] to-[#7C6FFF] text-white font-bold text-lg flex items-center justify-center gap-3 shadow-[0_8px_30px_rgb(0,0,0,0.12)] hover:scale-[1.01] active:scale-[0.99] transition-all disabled:opacity-50">
            <Sparkles size={20} />
            {isSaving ? "Saving to Registry..." : "Save Profile Configuration"}
          </button>
        </div>
      </div>

      {/* Floating Buttons */}
      <div className="fixed bottom-6 right-6 z-50">
        <button className="w-14 h-14 rounded-full bg-accent-primary text-white flex items-center justify-center shadow-lg hover:scale-110 active:scale-95 transition-transform">
          <MessageCircle size={28} />
        </button>
      </div>
    </>
  );
}

'use client';

import { TopNav } from '@/components/layout/TopNav';
import { LeftSidebar } from '@/components/layout/LeftSidebar';
import {
  Download, Copy, Edit3, Share2, MapPin, Mail, Link as LinkIcon, Plus, Zap, Key, AlertCircle
} from 'lucide-react';
import { useState } from 'react';

// Added a `@media print` style block to ensure ONLY the resume is printed into a pristine PDF!
const printStyles = `
  @media print {
    body * {
      visibility: hidden;
    }
    #resume-paper, #resume-paper * {
      visibility: visible;
    }
    #resume-paper {
      position: absolute;
      left: 0;
      top: 0;
      width: 100%;
      box-shadow: none !important;
      margin: 0 !important;
      padding: 0 !important;
    }
  }
`;

export default function ResumeView({ userData }: { userData: any }) {
  const [activeVersion, setActiveVersion] = useState('LaTeX-Professional');
  const [isEditing, setIsEditing] = useState(false);
  const [newSkill, setNewSkill] = useState('');

  const versions = [
    { id: 'LaTeX-Professional', label: 'Professional (LaTeX)', type: 'master' },
    { id: 'v1.2-Master', label: 'v1.2-Master', type: 'master' },
    { id: 'v1.1-Fintech', label: 'v1.1-Fintech Focus', type: 'focus' },
    { id: 'v1.0-Generic', label: 'v1.0-Generic', type: 'generic' },
  ];

  // Fallbacks if data is empty
  const name = userData?.name || 'Arjun Sharma';
  const email = userData?.email || 'arjun.sharma@example.com';
  const headline = userData?.profile?.headline || 'Full Stack Developer';
  
  const [editableSkills, setEditableSkills] = useState<string[]>(
    userData?.profile?.skills?.length > 0 
      ? userData.profile.skills.map((s: any) => s.name) 
      : ['React', 'Next.js', 'Node.js', 'TypeScript', 'Tailwind CSS', 'PostgreSQL']
  );
  
  const experiences = userData?.profile?.experience?.length > 0 ? userData.profile.experience : [];
  const education = userData?.profile?.education?.length > 0 ? userData.profile.education : [];
  const projects = userData?.profile?.projects?.length > 0 ? userData.profile.projects : [];
  const certificates = userData?.profile?.certificates?.length > 0 ? userData.profile.certificates : [];
  const githubUrl = userData?.profile?.githubUrl || '';
  const portfolioUrl = userData?.profile?.portfolioUrl || '';
  const atsScoreNum = userData?.profile?.atsScore || 87;

  const handleDownloadPdf = () => {
    // Triggers the native browser print, which allows Saving as PDF cleanly.
    window.print();
  };

  const handleCopyText = async () => {
    const paper = document.getElementById('resume-paper');
    if (paper) {
      try {
        await navigator.clipboard.writeText(paper.innerText);
        alert('Resume text copied to clipboard!');
      } catch (err) {
        console.error('Failed to copy', err);
      }
    }
  };

  const handleAddSkill = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && newSkill.trim()) {
      e.preventDefault();
      if (!editableSkills.includes(newSkill.trim())) {
        setEditableSkills([...editableSkills, newSkill.trim()]);
      }
      setNewSkill('');
    }
  };

  const removeSkill = (skillToRemove: string) => {
    setEditableSkills(editableSkills.filter(s => s !== skillToRemove));
  };

  return (
    <div className="min-h-screen bg-background">
      <style>{printStyles}</style>
      <TopNav />
      {/* Note: LeftSidebar highlight forced to 'Matching' per requirements */}
      <LeftSidebar activeItem="Matching" />

      <main className="pl-[220px] pt-[52px] pb-24 min-h-screen">
        <div className="max-w-[1400px] mx-auto p-8 flex gap-8">

          {/* LEFT COLUMN - Resume Preview (55%) */}
          <div className="w-[55%] flex flex-col gap-4">
            {/* Action Bar */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <button
                  onClick={handleDownloadPdf}
                  className="h-10 px-4 bg-[#ef4444] text-white rounded-lg flex items-center gap-2 text-sm font-bold hover:bg-red-600 transition-colors">
                  <Download size={18} />
                  Download PDF
                </button>
                <button 
                  onClick={handleCopyText}
                  className="h-10 px-4 border border-border-color text-text-primary rounded-lg flex items-center gap-2 text-sm font-medium hover:bg-card-surface transition-colors"
                >
                  <Copy size={18} />
                  Copy
                </button>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => setIsEditing(!isEditing)}
                  title="Toggle Edit Mode"
                  className={`p-2 transition-colors rounded ${isEditing ? 'bg-accent-primary text-white' : 'text-text-muted hover:text-text-primary'}`}
                >
                  <Edit3 size={20} />
                </button>
                <button className="p-2 text-text-muted hover:text-text-primary transition-colors">
                  <Share2 size={20} />
                </button>
              </div>
            </div>

            {/* Resume Paper (A4 Style) */}
            <div 
              id="resume-paper" 
              className={`bg-white rounded-lg min-h-[1000px] relative overflow-hidden text-black transition-all ${isEditing ? 'ring-2 ring-accent-primary shadow-lg border-transparent' : 'shadow-2xl'}`}
              contentEditable={isEditing}
              suppressContentEditableWarning={true}
            >
              {activeVersion === 'LaTeX-Professional' ? (
                /* LaTeX Professional Template */
                <div className="p-12 font-serif bg-white min-h-full">
                  {/* Header */}
                  <div className="text-center mb-6">
                    <h1 className="text-3xl font-bold uppercase tracking-wider mb-1">{name}</h1>
                    <div className="text-sm text-gray-700 mb-1">{userData?.location || 'Mysuru, Karnataka, India'}</div>
                    <div className="flex items-center justify-center gap-4 text-[11px] text-gray-800">
                      <div className="flex items-center gap-1">
                        <Zap size={10} className="fill-current" />
                        <span>7060510392</span>
                      </div>
                      <a href={`mailto:${email}`} className="flex items-center gap-1 underline underline-offset-2">
                        <Mail size={10} />
                        <span>{email}</span>
                      </a>
                      {githubUrl && (
                        <a href={githubUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 underline underline-offset-2">
                          <LinkIcon size={10} />
                          <span>{githubUrl.replace('https://', '')}</span>
                        </a>
                      )}
                      {portfolioUrl && (
                        <a href={portfolioUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 underline underline-offset-2">
                          <LinkIcon size={10} />
                          <span>{portfolioUrl.replace('https://', '')}</span>
                        </a>
                      )}
                    </div>
                  </div>

                  {/* Summary */}
                  <div className="mb-6">
                    <div className="flex flex-col mb-1 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Summary</h3>
                    </div>
                    <p className="text-[11.5px] leading-relaxed text-justify">
                      {headline}. Highly skilled professional with experience in building scalable solutions and delivering backend-driven applications. Actively strengthening problem-solving skills through Data Structures and Algorithms practice. Interested in scalable software systems and product engineering roles.
                    </p>
                  </div>

                  {/* Education */}
                  <div className="mb-6">
                    <div className="flex flex-col mb-2 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Education</h3>
                    </div>
                    {education.map((edu: any, i: number) => (
                      <div key={i} className="mb-2">
                        <div className="flex justify-between items-baseline mb-0.5">
                          <h4 className="font-bold text-[12px]">{edu.school}</h4>
                          <span className="text-[11px] italic">{edu.period}</span>
                        </div>
                        <div className="flex justify-between items-baseline">
                          <p className="text-[11px]">{edu.degree}</p>
                          <span className="text-[11px] font-bold">CGPA: 9.02</span>
                        </div>
                      </div>
                    ))}
                    {education.length === 0 && (
                      <div className="mb-2">
                        <div className="flex justify-between items-baseline mb-0.5">
                          <h4 className="font-bold text-[12px]">The National Institute of Engineering</h4>
                          <span className="text-[11px] italic">2024 -- 2028</span>
                        </div>
                        <div className="flex justify-between items-baseline">
                          <p className="text-[11px]">Bachelor of Engineering in Computer Science and Engineering</p>
                          <span className="text-[11px] font-bold">CGPA: 9.02</span>
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Coursework - Simulated */}
                  <div className="mb-6">
                    <div className="flex flex-col mb-2 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Relevant Coursework</h3>
                    </div>
                    <ul className="list-disc list-inside text-[11px] marker:text-black">
                      <li>Data Structures, Object Oriented Programming, Operating Systems, Computer Networks, Database Management Systems</li>
                    </ul>
                  </div>

                  {/* Projects */}
                  <div className="mb-6">
                    <div className="flex flex-col mb-2 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Projects</h3>
                    </div>
                    <div className="space-y-4">
                      {projects.map((p: any, i: number) => (
                        <div key={i}>
                          <div className="font-bold text-[12px] mb-1">
                            {p.name} <span className="font-normal mx-1">|</span> <span className="font-medium italic">Next.js, Express.js</span>
                          </div>
                          <ul className="list-disc list-outside ml-6 text-[11px] space-y-0.5">
                            <li>{p.description}</li>
                            {p.link && (
                              <li>
                                Live: <a href={p.link} className="underline">{p.link.replace('https://', '')}</a>
                              </li>
                            )}
                          </ul>
                        </div>
                      ))}
                      {projects.length === 0 && (
                        <>
                          <div>
                            <div className="font-bold text-[12px] mb-1">
                              Data Management Web Application (Freelance) <span className="font-normal mx-1">|</span> <span className="font-medium italic">Next.js, Express.js</span>
                            </div>
                            <ul className="list-disc list-outside ml-6 text-[11px] space-y-0.5">
                              <li>Built web app to manage structured operational data with modular validation logic.</li>
                              <li>Developed REST APIs using Express.js and dynamic UI using Next.js.</li>
                              <li>Live: <a href="#" className="underline">View Project</a></li>
                            </ul>
                          </div>
                          <div>
                            <div className="font-bold text-[12px] mb-1">
                              School Website (Freelance) <span className="font-normal mx-1">|</span> <span className="font-medium italic">HTML, CSS, JavaScript, EmailJS</span>
                            </div>
                            <ul className="list-disc list-outside ml-6 text-[11px] space-y-0.5">
                              <li>Developed responsive production-ready informational website.</li>
                              <li>Integrated EmailJS contact system and gathered stakeholder requirements.</li>
                              <li>Live: <a href="#" className="underline">View Project</a></li>
                            </ul>
                          </div>
                        </>
                      )}
                    </div>
                  </div>

                  {/* Skills */}
                  <div className="mb-6">
                    <div className="flex flex-col mb-2 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Skills</h3>
                    </div>
                    <div className="space-y-1.5 text-[11px]" contentEditable={false}>
                      <div className="flex flex-wrap gap-x-1 gap-y-1 items-center">
                        <span className="font-bold mr-1">Programming:</span> 
                        {editableSkills.map((skill: string, i: number) => (
                          <span key={i} className="flex items-center">
                            {skill}
                            {isEditing && (
                              <button 
                                onClick={() => removeSkill(skill)}
                                className="text-red-500 hover:text-red-700 ml-0.5 mr-0.5 font-bold flex items-center justify-center text-[11px]"
                              >
                                ×
                              </button>
                            )}
                            {i < editableSkills.length - 1 && <span>,</span>}
                          </span>
                        ))}
                        {isEditing && (
                          <input
                            type="text"
                            placeholder="+ Add (Press Enter)"
                            value={newSkill}
                            onChange={(e) => setNewSkill(e.target.value)}
                            onKeyDown={handleAddSkill}
                            className="px-1 py-0.5 border border-dashed border-gray-400 rounded text-[10px] outline-none w-28 bg-transparent ml-1"
                          />
                        )}
                      </div>
                      <div>
                        <span className="font-bold">Core Computer Science:</span> Data Structures, OOP, Problem Solving
                      </div>
                      <div>
                        <span className="font-bold">Backend / Server-Side:</span> Next.js, Express.js, REST APIs
                      </div>
                      <div>
                        <span className="font-bold">Frontend / Web:</span> HTML, CSS, React
                      </div>
                      <div>
                        <span className="font-bold">Tools:</span> Git, VS Code
                      </div>
                    </div>
                  </div>

                  {/* Leadership */}
                  <div className="mb-6">
                    <div className="flex flex-col mb-2 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Leadership</h3>
                    </div>
                    <div className="flex justify-between items-baseline mb-1">
                      <h4 className="font-bold text-[12px]">Team Lead — Viswakarma Award Project</h4>
                      <span className="text-[11px] italic">2025</span>
                    </div>
                    <ul className="list-disc list-outside ml-6 text-[11px]">
                      <li>Led LoRa-based vehicle communication prototype design and demonstration.</li>
                    </ul>
                  </div>

                  {/* Achievements */}
                  <div>
                    <div className="flex flex-col mb-2 pt-1 border-b border-black">
                      <h3 className="text-sm font-bold uppercase tracking-widest text-left">Achievements</h3>
                    </div>
                    <ul className="list-disc list-outside ml-6 text-[11px]">
                      <li>
                        <span className="font-bold text-black">12th Rank — Viswakarma Award 2025</span> <span> </span>
                        <a href="#" className="underline">(Certificate)</a>
                      </li>
                    </ul>
                  </div>
                </div>
              ) : (
                /* Original Modern Template */
                <div className="p-10 font-sans">
                  {/* Watermark */}
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] rotate-[-45deg] select-none">
                    <span className="text-9xl font-bold">JobAgent</span>
                  </div>

                  {/* Header */}
                  <div className="relative z-10 mb-8">
                    <h1 className="text-3xl font-bold mb-1">{name}</h1>
                    <h2 className="text-lg font-medium text-[#4F6BED] mb-4">{headline}</h2>

                    <div className="flex flex-wrap gap-4 text-sm text-gray-600">
                      <div className="flex items-center gap-1.5">
                        <Mail size={14} />
                        <span>{email}</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <MapPin size={14} />
                        <span>{userData?.location || 'San Francisco, CA'}</span>
                      </div>
                      {githubUrl && (
                        <div className="flex items-center gap-1.5">
                          <LinkIcon size={14} />
                          <span>{githubUrl.replace('https://', '')}</span>
                        </div>
                      )}
                      {portfolioUrl && (
                        <div className="flex items-center gap-1.5">
                          <LinkIcon size={14} />
                          <span>{portfolioUrl.replace('https://', '')}</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Summary */}
                  <div className="relative z-10 mb-8">
                    <div className="flex items-center gap-3 mb-2">
                      <span className="text-xs font-bold text-teal-600 tracking-widest">PROFESSIONAL SUMMARY</span>
                      <div className="flex-1 h-[1px] bg-gray-200" />
                    </div>
                    <p className="text-sm leading-relaxed text-gray-800">
                      Highly skilled professional with experience in building scalable solutions. Proven track record of improving deployment efficiency and system performance. Passionate about creating seamless user experiences and robust backend systems based on dynamic database generation!
                    </p>
                  </div>

                  {/* Skills */}
                  <div className="relative z-10 mb-8">
                    <div className="flex items-center gap-3 mb-4">
                      <span className="text-xs font-bold text-teal-600 tracking-widest uppercase">Technical Skills</span>
                      <div className="flex-1 h-[1px] bg-gray-200" />
                    </div>
                    <div className="grid grid-cols-2 gap-8">
                      <div className="col-span-2" contentEditable={false}>
                        <div className="flex flex-wrap gap-2 items-center">
                          {editableSkills.map((skill: string, i: number) => (
                            <span key={i} className="px-2 py-0.5 border border-gray-200 rounded text-[11px] text-gray-700 flex items-center gap-1">
                              {skill}
                              {isEditing && (
                                <button 
                                  onClick={() => removeSkill(skill)}
                                  className="text-red-500 hover:text-red-700 text-xs font-bold w-3 h-3 flex items-center justify-center leading-none"
                                >
                                  ×
                                </button>
                              )}
                            </span>
                          ))}
                          {isEditing && (
                            <input
                              type="text"
                              placeholder="+ Add Skill (Press Enter)"
                              value={newSkill}
                              onChange={(e) => setNewSkill(e.target.value)}
                              onKeyDown={handleAddSkill}
                              className="px-2 py-0.5 border border-dashed border-gray-400 rounded text-[11px] text-gray-700 outline-none w-36 bg-transparent"
                            />
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Experience */}
                  <div className="relative z-10">
                    <div className="flex flex-col gap-6">
                      {experiences.map((exp: any, i: number) => (
                        <div key={i}>
                          <div className="flex items-start justify-between mb-1">
                            <h3 className="font-bold text-[15px]">{exp.company}</h3>
                            <span className="text-xs text-gray-500 italic">{exp.period}</span>
                          </div>
                          <div className="text-[#4F6BED] text-sm font-semibold mb-2">{exp.title}</div>
                          <ul className="list-disc list-outside ml-4 space-y-1.5">
                            <li className="text-sm text-gray-800">{exp.description}</li>
                          </ul>
                        </div>
                      ))}
                      {experiences.length === 0 && <p className="text-xs text-gray-400 italic">No experience listed.</p>}
                    </div>
                  </div>

                  {/* Education & Projects */}
                  <div className="relative z-10 grid grid-cols-2 gap-8 mt-8">
                    <div>
                      <div className="flex items-center gap-3 mb-4">
                        <span className="text-xs font-bold text-teal-600 tracking-widest uppercase">Education</span>
                        <div className="flex-1 h-[1px] bg-gray-200" />
                      </div>
                      {education.map((edu: any, i: number) => (
                        <div key={i} className="mb-4">
                          <h4 className="font-bold text-sm">{edu.school}</h4>
                          <p className="text-xs text-gray-700">{edu.degree}</p>
                          <p className="text-[10px] text-gray-500 italic">{edu.period}</p>
                        </div>
                      ))}
                      {education.length === 0 && <p className="text-xs text-gray-400 italic">No education listed.</p>}
                    </div>
                    <div>
                      <div className="flex items-center gap-3 mb-4">
                        <span className="text-xs font-bold text-teal-600 tracking-widest uppercase">Projects</span>
                        <div className="flex-1 h-[1px] bg-gray-200" />
                      </div>
                      {projects.map((p: any, i: number) => (
                        <div key={i} className="mb-4">
                          <h4 className="font-bold text-sm">{p.name}</h4>
                          <p className="text-xs text-gray-800 line-clamp-2">{p.description}</p>
                          {p.link && <p className="text-[10px] text-blue-600 truncate">{p.link}</p>}
                        </div>
                      ))}
                      {projects.length === 0 && <p className="text-xs text-gray-400 italic">No projects listed.</p>}
                    </div>
                  </div>

                  {/* Certificates */}
                  {certificates.length > 0 && (
                    <div className="relative z-10 mt-8">
                      <div className="flex items-center gap-3 mb-4">
                        <span className="text-xs font-bold text-teal-600 tracking-widest uppercase">Certifications</span>
                        <div className="flex-1 h-[1px] bg-gray-200" />
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        {certificates.map((c: any, i: number) => (
                          <div key={i}>
                            <h4 className="font-bold text-xs">{c.name}</h4>
                            <p className="text-[10px] text-gray-600">{c.issuer} · {c.date}</p>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Versions Footer */}
            <div className="flex items-center gap-3 mt-4">
              <span className="text-[10px] font-bold text-text-muted uppercase tracking-wider">Versions:</span>
              <div className="flex items-center gap-2">
                {versions.map((v) => (
                  <button
                    key={v.id}
                    onClick={() => setActiveVersion(v.id)}
                    className={`px-3 py-1 rounded-full text-[11px] font-medium transition-all ${activeVersion === v.id
                        ? 'bg-accent-primary text-white'
                        : 'bg-input-bg text-text-muted hover:text-text-primary'
                      }`}
                  >
                    {v.label}
                  </button>
                ))}
                <button className="w-6 h-6 rounded-full bg-input-bg border border-input-border flex items-center justify-center text-text-muted hover:text-text-primary transition-colors">
                  <Plus size={14} />
                </button>
              </div>
            </div>
          </div>

          {/* RIGHT COLUMN - Stats & Recommendations (43%) */}
          <div className="w-[43%] flex flex-col gap-6">

            {/* Card 1 - ATS Intelligence */}
            <div className="glass-card p-6">
              <div className="flex items-center gap-2 mb-8">
                <Zap size={20} className="text-teal-400" />
                <h3 className="text-sm font-bold text-text-primary uppercase tracking-wider">ATS Intelligence</h3>
              </div>

              <div className="flex flex-col items-center mb-8">
                <div className="relative w-[160px] h-[160px]">
                  <svg className="w-full h-full transform -rotate-90">
                    <circle
                      cx="80"
                      cy="80"
                      r="70"
                      stroke="currentColor"
                      strokeWidth="10"
                      fill="transparent"
                      className="text-[#1a1a28]"
                    />
                    <circle
                      cx="80"
                      cy="80"
                      r="70"
                      stroke="currentColor"
                      strokeWidth="10"
                      fill="transparent"
                      strokeDasharray={2 * Math.PI * 70}
                      strokeDashoffset={2 * Math.PI * 70 * (1 - (atsScoreNum / 100))}
                      strokeLinecap="round"
                      className="text-[#22c55e]"
                    />
                  </svg>
                  <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-4xl font-bold text-text-primary">{atsScoreNum}%</span>
                    <span className="text-[10px] font-bold text-text-muted uppercase mt-1">Match Score</span>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="text-center">
                  <div className="text-lg font-bold text-[#22c55e]">92%</div>
                  <div className="text-[10px] text-text-hint font-bold uppercase">Role</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold text-[#22c55e]">100%</div>
                  <div className="text-[10px] text-text-hint font-bold uppercase">Format</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold text-amber-500">74%</div>
                  <div className="text-[10px] text-text-hint font-bold uppercase">Read</div>
                </div>
              </div>
            </div>

            {/* Card 2 - Keyword Density */}
            <div className="glass-card p-6">
              <div className="flex items-center gap-2 mb-6">
                <Key size={18} className="text-accent-primary" />
                <h3 className="text-sm font-bold text-text-primary uppercase tracking-wider">Keyword Density</h3>
              </div>

              <div className="space-y-6">
                <div>
                  <div className="text-[10px] font-bold text-text-muted uppercase mb-3">Detected Keywords</div>
                  <div className="flex flex-wrap gap-2">
                    {['React ✓', 'Node.js ✓', 'CI/CD ✓'].map(kw => (
                      <span key={kw} className="px-3 py-1 bg-[#1e293b] text-[#22c55e] border border-[#22c55e]/20 rounded-full text-[11px] font-semibold">
                        {kw}
                      </span>
                    ))}
                  </div>
                </div>

                <div>
                  <div className="text-[10px] font-bold text-text-muted uppercase mb-3">Missing / Critical</div>
                  <div className="flex flex-wrap gap-2">
                    {['Docker !', 'Kubernetes !'].map(kw => (
                      <span key={kw} className="px-3 py-1 bg-[#332a1a] text-amber-500 border border-amber-500/20 rounded-full text-[11px] font-semibold">
                        {kw}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Card 3 - AI Recommendations */}
            <div className="glass-card p-6 flex-1">
              <div className="flex items-center gap-2 mb-6">
                <AlertCircle size={18} className="text-amber-500" />
                <h3 className="text-sm font-bold text-text-primary uppercase tracking-wider">AI Recommendations</h3>
              </div>

              <div className="space-y-6">
